package com.acme.order.order;
import com.acme.order.common.core.*;import jakarta.validation.Valid;import org.slf4j.MDC;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;}@PostMapping("/settlement") ApiResponse<OrderDtos.SettlementView> settlement(@Valid @RequestBody OrderDtos.SettlementRequest r){return ApiResponse.ok(s.settle(r.items()),MDC.get("traceId"));}@PostMapping ApiResponse<OrderDtos.OrderView> create(@RequestHeader("X-User-Id")long u,@RequestHeader("X-Idempotency-Token")String t,@Valid @RequestBody OrderDtos.CreateRequest r){return ApiResponse.ok(s.create(u,t,r.items()),MDC.get("traceId"));}@GetMapping ApiResponse<java.util.List<OrderDtos.OrderView>> list(@RequestHeader("X-User-Id")long u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.list(u,page,size),MDC.get("traceId"));}@GetMapping("/{no}") ApiResponse<OrderDtos.OrderView> get(@PathVariable String no,@RequestHeader("X-User-Id")long u){return ApiResponse.ok(s.view(no,u),MDC.get("traceId"));}@PostMapping("/{no}/cancel") ApiResponse<Void> cancel(@PathVariable String no,@RequestHeader("X-User-Id")long u){s.cancel(no,u,"USER");return ApiResponse.ok(null,MDC.get("traceId"));}@PostMapping("/{no}/pay") ApiResponse<OrderDtos.PayView> pay(@PathVariable String no,@RequestHeader("X-User-Id")long u){return ApiResponse.ok(s.pay(no,u),MDC.get("traceId"));}@PostMapping("/{no}/deliver")ApiResponse<Void> deliver(@PathVariable String no,@RequestHeader("X-User-Id")long u){s.deliver(no,u);return ApiResponse.ok(null,MDC.get("traceId"));}@PostMapping("/{no}/receive")ApiResponse<Void> receive(@PathVariable String no,@RequestHeader("X-User-Id")long u){s.receive(no,u);return ApiResponse.ok(null,MDC.get("traceId"));}}
